g),\\r\\n  35: \\r\\n  36:     /// An option was given that does nothing when either of two other options\\r\\n  37:     /// are not present.\\r\\n  38:     Useless2(&'static Arg, &'static Arg, &'static Arg),\\r\\n  39: \\r\\n  40:     /// A very specific edge case where --tree can’t be used with --all twice.\\r\\n  41:     TreeAllAll,\\r\\n  42: \\r\\n  43:     /// A numeric option was given that failed to be parsed as a number.\\r\\n  44:     FailedParse(String, NumberSource, ParseIntError),\\r\\n  45: \\r\\n  46:     /// A glob ignore was given that failed to be parsed as a pattern.\\r\\n  47:     FailedGlobPattern(String),\\r\\n  48: }\\r\\n  49: \\r\\n  50: /// The source of a string that failed to be parsed as a number.\\r\\n  51: #[derive(PartialEq, Eq, Debug)]\\r\\n  52: pub enum NumberSource {\\r\\n  53:     /// It came... from a command-line argument!\\r\\n  54:     Arg(&'static Arg),\\r\\n  55: \\r\\n  56:     /// It came... from the environment!\\r\\n  57:     Env(&'static str),\\r\\n  58: }\\r\\n  59: \\r\\n  60: impl From<glob::PatternError> for OptionsError {\\r\\n  61:     fn from(error: glob::PatternError) -> Self {\\r\\n  62:         Self::FailedGlobPattern(error.to_string())\\r\\n  63:     }\\r\\n  64: }\\r\\n  65: \\r\\n  66: impl fmt::Display for NumberSource {\\r\\n  67:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\\r\\n  68:         match self {\\r\\n  69:             Self::Arg(arg) => write!(f, \\\"option {arg}\\\"),\\r\\n  70:             Self::Env(env) => write!(f, \\\"environment variable {env}\\\"),\\r\\n  71:         }\\r\\n  72:     }\\r\\n  73: }\\r\\n  74: \\r\\n  75: impl fmt::Display for OptionsError {\\r\\n  76:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\\r\\n  77:         use crate::options::parser::TakesValue;\\r\\n  78: \\r\\n  79:         #[rustfmt::skip]\\r\\n  80:         return match self {\\r\\n  81:             Self::BadArgument(arg, attempt) => {\\r\\n  82:                 if let Take