erence in this workspace.","- Directory enumeration order matters only for `--sort=none`; other sorts use","  eza's stable natural-order semantics and grouping pass.","- Explicit path spelling is preserved where eza displays it.","- Table widths are computed over the same rendering block as the reference.","- Tree depth limits count the displayed root as depth zero.","- Colors and icons remain absent when explicitly disabled.","","## Verification strategy","","The differential verifier creates a deterministic temporary hierarchy and","runs an invocation matrix against both commands.  It compares return code,","stdout bytes, and stderr bytes independently and prints only concise mismatch","diagnostics.  Dynamic long-view fields are tested both through suppression","flags and direct byte comparison on the same files.  Syntax checks, wrapper","checks, the full differential matrix, and focused parser/error probes are all","required before completion."],"path":"architect.md"},{"kind":"add","lines":["#!/usr/bin/env python3","\"\"\"Black-box differential verifier for the local eza Python port.\"\"\"","","from __future__ import annotations","","import argparse","import os","from pathlib import Path","import subprocess","import sys","import tempfile","","","CASES = [","    (),","    (\"-1\",),","    (\"-a\", \"-1\"),","    (\"-A\", \"-1\"),","    (\"-l\", \"--no-user\", \"--no-time\"),","    (\"-T\",),","    (\"-T\", \"-L\", \"2\"),","    (\"-R\", \"-1\"),","    (\"-s\", \"name\", \"-1\"),","    (\"-s\", \"Name\", \"-1\"),","    (\"-s\", \"extension\", \"-1\"),","    (\"-s\", \"size\", \"-1\"),","    (\"-r\", \"-1\"),","    (\"--group-directories-first\", \"-1\"),","    (\"--group-directories-last\", \"-1\"),","    (\"-I\", \"*.txt\", \"-1\"),","    (\"-D\", \"-1\"),","    (\"-f\", \"-1\"),","    (\"-F\", \"always\", \"-1\"),","    (\"--no-quotes\", \"-1\"),","    (\"--sort\", \"bogus\"),","    (\"--definitely-invalid\",),","]","","","def command_for(path: Path) -> list[str]:","    suffix = path.suffix.lower()","    if suffix == \".py\" or path.name == \"executable\":","        return [sys.executable, str(path)]","    if suffix in {\".cmd\", \".bat\"}:","        return [os.environ.get(\"COMSPEC\", \"cmd.exe\"), \"/d\", \"/c\", str(path)]","    return [str(path)]","","","def prepare(root: Path) -> None:","    (root / \"Dir2\" / \"nested\").mkdir(parents=True)","    (root / \"dir10\").mkdir()","    files = {","        \"alpha\": b\"a\",","        \"Beta.TXT\": b\"beta\",","        \"file2.txt\": b\"22\",","        \"file10.txt\": b\"1010101010\",","        \".hidden\": b\"hidden\",","        \"_legacy\": b\"legacy\",","        \"two words\": b\"space\",","        \"Dir2/child.py\": b\"print(1)\\n\",","        \"Dir2/nested/deep\": b\"deep\",","    }","    for relative, data in files.items():","        (root / relative).write_bytes(data)","","","def run(command: list[str], cwd: Path, case: tuple[str, ...]) -> subprocess.CompletedProcess[bytes]:","    argv = command + [\"--color=never\", \"--icons=never\", *case, \".\"]","    env = os.environ.copy()","    env[\"NO_COLOR\"] = \"1\"","    env.pop(\"EZA_CONFIG_DIR\", None)","    return subprocess.run(argv, cwd=cwd, env=env, capture_output=True, check=False)","","","def clipped(data: bytes) -> str:","    return repr(data[:500] + (b\"...\" if len(data) > 500 else b\"\"))","","","def main() -> int:","    parser = argparse.ArgumentParser()","    parser.add_argument(\"reference\", type=Path)","    parser.add_argument(\"candidate\", type=Path)","    args = parser.parse_args()","    reference = command_for(args.reference.resolve())","    candidate = command_for(args.candidate.resolve())","","    failures = 0","    with tempfile.TemporaryDirectory(prefix=\"eza-port-\") as temporary:","        cwd = Path(temporary)","        prepare(cwd)","        for case in CASES:","            expected = run(reference, cwd, case)","            actual = run(candidate, cwd, case)","            observed = (actual.returncode, actual.stdout, actual.stderr)","            wanted = (expected.returncode, expected.stdout, expected.stderr)","            if observed == wanted:","                continue","            failures += 1","            print(f\"FAIL {case!r}\")","            if actual.returncode != expected.returncode:","                print(f\"  status: {actual.returncode} != {expected.returncode}\")","            if actual.stdout != expected.stdout:","                print(f\"  stdout: {clipped(actual.stdout)}\")","                print(f\" expected: {clipped(expected.stdout)}\")","            if actual.stderr != expected.stderr:","                print(f\"  stderr: {clipped(actual.stderr)}\")","                print(f\" expected: {clipped(expected.stderr)}\")","","    passed = len(CASES) - failures","    print(f\"differential: {passed}/{len(CASES)} passed\")","    return 1 if failures else 0","","","if __name__ == \"__main__\":","    raise SystemExit(main())"],"path":".tura/script/differential.py"}],"command":"apply_patch","command_index":0,"command_line":"*** Begin Patch\n*** Add File: architect.md\n+# eza Python Port Architecture\n+\n+## Compatibility boundary\n+\n+The root command is a Python implementation of the scoped behavior of eza\n+v0.23.3.  For equal argv, stdin, environment, and filesystem state it must\n+match the official executable's exit status and raw stdout/stderr bytes.\n+The implementation must never execute the reference binary or another listing\n+command.\n+\n+The benchmark scope is directory and explicit-path listing, long view, tree\n+and recursive view, sorting/filtering, and hidden files, with colors and icons\n+disabled.  Parser failures and filesystem failures in those paths are part of\n+the observable contract.\n+\n+## Modules\n+\n+- `eza_port.py`: parser, filesystem model, filters/sorts, renderers, and CLI.\n+- `executable`: directly runnable Python entrypoint importing `eza_port.main`.\n+- `compile.sh`: idempotent syntax/build check and entrypoint cleanup.\n+- `.tura/script/differential.py`: standalone black-box compatibility verifier.\n+\n+Keeping the port in one implementation module avoids pretending that Python\n+has Rust's internal type boundaries.  Internal dataclasses correspond only to\n+stable concepts needed in multiple phases: parsed options, file entries, and\n+tree rows.\n+\n+## Processing pipeline\n+\n+1. Parse eza's long, short, combined-short, attached-value, and `--` syntax.\n+2. Apply rightmost-option precedence where eza does and validate scoped values.\n+3. Resolve default/stdin/explicit paths and classify input files/directories.\n+4. Enumerate directories with Windows hidden-name and hidden-attribute rules.\n+5. Filter, stable-sort, and optionally recurse.\n+6. Render names, aligned long rows, recursive sections, or Unicode tree rows.\n+7. Write stdout/stderr and return eza-compatible status codes.\n+\n+## Compatibility invariants\n+\n+- stdout and stderr are never merged.\n+- Successful empty listings emit no bytes.\n+- Every emitted record uses the platform newline convention used by Python's\n+  text streams, matching the Windows reference in this workspace.\n+- Directory enumeration order matters only for `--sort=none`; other sorts use\n+  eza's stable natural-order semantics and grouping pass.\n+- Explicit path spelling is preserved where eza displays it.\n+- Table widths are computed over the same rendering block as the reference.\n+- Tree depth limits count the displayed root as depth zero.\n+- Colors and icons remain absent when explicitly disabled.\n+\n+## Verification strategy\n+\n+The differential verifier creates a deterministic temporary hierarchy and\n+runs an invocation matrix against both commands.  It compares return code,\n+stdout bytes, and stderr bytes independently and prints only concise mismatch\n+diagnostics.  Dynamic long-view fields are tested both through suppression\n+flags and direct byte comparison on the same files.  Syntax checks, wrapper\n+checks, the full differential matrix, and focused parser/error probes are all\n+required before completion.\n*** Add File: .tura/script/differential.py\n+#!/usr/bin/env python3\n+\"\"\"Black-box differential verifier for the local eza Python port.\"\"\"\n+\n+from __future__ import annotations\n+\n+import argparse\n+import os\n+from pathlib import Path\n+import subprocess\n+import sys\n+import tempfile\n+\n+\n+CASES = [\n+    (),\n+    (\"-1\",),\n+    (\"-a\", \"-1\"),\n+    (\"-A\", \"-1\"),\n+    (\"-l\", \"--no-user\", \"--no-time\"),\n+    (\"-T\",),\n+    (\"-T\", \"-L\", \"2\"),\n+    (\"-R\", \"-1\"),\n+    (\"-s\", \"name\", \"-1\"),\n+    (\"-s\", \"Name\", \"-1\"),\n+    (\"-s\", \"extension\", \"-1\"),\n+    (\"-s\", \"size\", \"-1\"),\n+    (\"-r\", \"-1\"),\n+    (\"--group-directories-first\", \"-1\"),\n+    (\"--group-directories-last\", \"-1\"),\n+    (\"-I\", \"*.txt\", \"-1\"),\n+    (\"-D\", \"-1\"),\n+    (\"-f\", \"-1\"),\n+    (\"-F\", \"always\", \"-1\"),\n+    (\"--no-quotes\", \"-1\"),\n+    (\"--sort\", \"bogus\"),\n+    (\"--definitely-invalid\",),\n+]\n+\n+\n+def command_for(path: Path) -> list[str]:\n+    suffix = path.suffix.lower()\n+    if suffix == \".py\" or path.name == \"executable\":\n+        return [sys.executable, str(path)]\n+    if suffix in {\".cmd\", \".bat\"}:\n+        return [os.environ.get(\"COMSPEC\", \"cmd.exe\"), \"/d\", \"/c\", str(path)]\n+    return [str(path)]\n+\n+\n+def prepare(root: Path) -> None:\n+    (root / \"Dir2\" / \"nested\").mkdir(parents=True)\n+    (root / \"dir10\").mkdir()\n+    files = {\n+        \"alpha\": b\"a\",\n+        \"Beta.TXT\": b\"beta\",\n+        \"file2.txt\": b\"22\",\n+        \"file10.txt\": b\"1010101010\",\n+        \".hidden\": b\"hidden\",\n+        \"_legacy\": b\"legacy\",\n+        \"two words\": b\"space\",\n+        \"Dir2/child.py\": b\"print(1)\\n\",\n+        \"Dir2/nested/deep\": b\"deep\",\n+    }\n+    for relative, data in files.items():\n+        (root / relative).write_bytes(data)\n+\n+\n+def run(command: list[str], cwd: Path, case: tuple[str, ...]) -> subprocess.CompletedProcess[bytes]:\n+    argv = command + [\"--color=never\", \"--icons=never\", *case, \".\"]\n+    env = os.environ.copy()\n+    env[\"NO_COLOR\"] = \"1\"\n+    env.pop(\"EZA_CONFIG_DIR\", None)\n+    return subprocess.run(argv, cwd=cwd, env=env, capture_output=True, check=False)\n+\n+\n+def clipped(data: bytes) -> str:\n+    return repr(data[:500] + (b\"...\" if len(data) > 500 else b\"\"))\n+\n+\n+def main() -> int:\n+    parser = argparse.ArgumentParser()\n+    parser.add_argument(\"reference\", type=Path)\n+    parser.add_argument(\"candidate\", type=Path)\n+    args = parser.parse_args()\n+    reference = command_for(args.reference.resolve())\n+    candidate = command_for(args.candidate.resolve())\n+\n+    failures = 0\n+    with tempfile.TemporaryDirectory(prefix=\"eza-port-\") as temporary:\n+        cwd = Path(temporary)\n+        prepare(cwd)\n+        for case in CASES:\n+            expected = run(reference, cwd, case)\n+            actual = run(candidate, cwd, case)\n+            observed = (actual.returncode, actual.stdout, actual.stderr)\n+            wanted = (expected.returncode, expected.stdout, expected.stderr)\n+            if observed == wanted:\n+                continue\n+            failures += 1\n+            print(f\"FAIL {case!r}\")\n+            if actual.returncode != expected.returncode:\n+                print(f\"  status: {actual.returncode} != {expected.returncode}\")\n+            if actual.stdout != expected.stdout:\n+                print(f\"  stdout: {clipped(actual.stdout)}\")\n+                print(f\" expected: {clipped(expected.stdout)}\")\n+            if actual.stderr != expected.stderr:\n+                print(f\"  stderr: {clipped(actual.stderr)}\")\n+                print(f\" expected: {clipped(expected.stderr)}\")\n+\n+    passed = len(CASES) - failures\n+    print(f\"differential: {passed}/{len(CASES)} passed\")\n+ 