rror> {\\r\\n  66:         if let Some(level) = matches.get(&flags::LEVEL)? {\\r\\n  67:             let arg_str = level.to_string_lossy();\\r\\n  68:             match arg_str.parse() {\\r\\n  69:                 Ok(l) => Ok(Self {\\r\\n  70:                     tree,\\r\\n  71:                     max_depth: Some(l),\\r\\n  72:                 }),\\r\\n  73:                 Err(e) => {\\r\\n  74:                     let source = NumberSource::Arg(&flags::LEVEL);\\r\\n  75:                     Err(OptionsError::FailedParse(arg_str.to_string(), source, e))\\r\\n  76:                 }\\r\\n  77:             }\\r\\n  78:         } else {\\r\\n  79:             Ok(Self {\\r\\n  80:                 tree,\\r\\n  81:                 max_depth: None,\\r\\n  82:             })\\r\\n  83:         }\\r\\n  84:     }\\r\\n  85: }\\r\\n  86: \\r\\n  87: #[cfg(test)]\\r\\n  88: mod test {\\r\\n  89:     use super::*;\\r\\n  90:     use crate::options::flags;\\r\\n\"}","command":"shell_command","command_index":1,"command_line":"{\"command\":\"$p='rust-reference/src/options/filter.rs'; $n=1; Get-Content $p | ForEach-Object {if($n -ge 100 -and $n -le 240){('{0,4}: {1}' -f $n,$_)};$n++}; $p='rust-reference/src/options/dir_action.rs'; $n=1; Get-Content $p | ForEach-Object {if($n -le 90){('{0,4}: {1}' -f $n,$_)};$n++}\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-97dfd29d0e\\\\eza\\\\tura-balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c0fdd75e8f1c60.tool.command_run:call_pCcaXYkfFXBPEg88ayI5qhbf:1","provider_tool_call_id":"call_pCcaXYkfFXBPEg88ayI5qhbf","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
