                   choices = VALUE_CHOICES.get(name)\",\"                        suffix = f\\\" (choices: {choices})\\\" if choices else \\\"\\\"\",\"                        raise parse_error(f\\\"Flag -{short} needs a value{suffix}\\\")\",\"                    options.occurrences.append((name, value))\",\"                elif name in OPTIONAL:\",\"                    if offset < len(chars):\",\"                        value = chars[offset:]\",\"                        if value.startswith(\\\"=\\\"):\",\"                            value = value[1:]\",\"                        offset = len(chars)\",\"                    elif index < len(argv) and argv[index] in VALUE_CHOICES.get(name, \\\"\\\").split(\\\", \\\"):\",\"                        value = argv[index]\",\"                        index += 1\",\"                    else:\",\"                        value = \\\"auto\\\"\",\"                    options.occurrences.append((name, value))\",\"                else:\",\"                    options.occurrences.append((name, None))\",\"            continue\",\"        options.paths.append(token)\",\"\",\"    deduce(options)\",\"    return options\",\"\",\"\",\"def validate_choice(options: Options, name: str, accepted: set[str], shown: str | None = None) -> None:\",\"    item = options.last(name)\",\"    if item is not None and item[1] not in accepted:\",\"        choices = f\\\" (choices: {shown})\\\" if shown else \\\"\\\"\",\"        raise CliError(f\\\"Option --{name}\\\" + (f\\\" (-{NECESSARY[name]})\\\" if NECESSARY.get(name) else \\\"\\\")\",\"                       + f\\\" has no {rust_debug(item[1] or '')} setting{choices}\\\")\",\"\",\"\",\"def parse_nonnegative(options: Options, name: str) -> int | None:\",\"    item = options.last(name)\",\"    if item is None:\",\"        return None\",\"    value = item[1] or \\\"\\\"\",\"    try:\",\"        number = int(value, 10)\",\"        if number < 0:\",\"            raise ValueError\",\"        return number\",\"    except ValueError as error:\",\"        detail = \\\"invalid digit found in string\\\" if not value.isdigit() else \\\"number too large to fit in target type\\\"\",\"        raise CliError(f'Value {rust_debug(value)} not valid for option --{name} (-{NECESSARY[name]}): {detail}') from error\",\"\",\"\",\"def deduce(options: Options) -> None:\",\"    validate_choice(options, \\\"sort\\\", {\",\"        \\\"name\\\", \\\"filename\\\", \\\"Name\\\", \\\"Filename\\\", \\\".name\\\", \\\".filename\\\", \\\".Name\\\", \\\".Filename\\\",\",\"        \\\"size\\\", \\\"filesize\\\", \\\"ext\\\", \\\"extension\\\", \\\"Ext\\\", \\\"Extension\\\", \\\"date\\\", \\\"time\\\", \\\"mod\\\",\",\"        \\\"modified\\\", \\\"new\\\", \\\"newest\\\", \\\"age\\\", \\\"old\\\", \\\"oldest\\\", \\\"ch\\\", \\\"changed\\\", \\\"acc\\\",\",\"        \\\"accessed\\\", \\\"cr\\\", \\\"created\\\", \\\"inode\\\", \\\"type\\\", \\\"none\\\",\",\"    }, SORT_CHOICES)\",\"    for name in (\\\"color\\\", \\\"colour\\\", \\\"icons\\\", \\\"classify\\\"):\",\"        validate_choice(options, name, {\\\"always\\\", \\\"auto\\\", \\\"automatic\\\", \\\"never\\\"})\",\"    validate_choice(options, \\\"absolute\\\", {\\\"on\\\", \\\"follow\\\", \\\"off\\\"})\",\"    validate_choice(options, \\\"time\\\", {\\\"mod\\\", \\\"modified\\\", \\\"ch\\\", \\\"changed\\\", \\\"acc\\\", \\\"accessed\\\", \\\"cr\\\", \\\"created\\\"}, TIME_CHOICES)\",\"\",\"    view = None\",\"    for name, _ in reversed(options.occurrences):\",\"        if name in {\\\"long\\\", \\\"oneline\\\", \\\"grid\\\", \\\"tree\\\"}:\",\"            view = name\",\"            break\",\"    if view == \\\"long\\\" or (view in {\\\"tree\\\", \\\"grid\\\"} and options.has(\\\"long\\\")):\",\"        options.mode = \\\"long\\\"\",\"    elif view == \\\"tree\\\":\",\"        options.mode = \\\"tree\\\"\",\"    elif view == \\\"grid\\\":\",\"        options.mode = \\\"grid\\\"\",\"    elif view == \\\"oneline\\\" or not sys.stdout.isatty