options.dirs_last:\",\"        result.sort(key=lambda entry: entry.points_to_dir)\",\"    return result\",\"\",\"\",\"def windows_hidden(path: Path) -> bool:\",\"    try:\",\"        attributes = path.stat(follow_symlinks=False).st_file_attributes\",\"    except (AttributeError, OSError):\",\"        return False\",\"    return bool(attributes & stat.FILE_ATTRIBUTE_HIDDEN)\",\"\",\"\",\"def children(directory: Path, options: Options, recursing: bool) -> list[Entry]:\",\"    found: list[Entry] = []\",\"    if options.dot_mode == \\\"dots\\\":\",\"        found.extend([\",\"            Entry(directory, \\\".\\\", is_dot=True),\",\"            Entry(directory / \\\"..\\\", \\\"..\\\", is_dot=True),\",\"        ])\",\"    with os.scandir(directory) as scan:\",\"        for item in scan:\",\"            name = item.name\",\"            hidden = name.startswith(\\\".\\\") or (os.name == \\\"nt\\\" and name.startswith(\\\"_\\\")) or windows_hidden(Path(item.path))\",\"            if hidden and options.dot_mode == \\\"none\\\":\",\"                continue\",\"            entry = Entry(Path(item.path), name)\",\"            found.append(entry)\",\"    filtered: list[Entry] = []\",\"    for entry in found:\",\"        if any(fnmatch.fnmatchcase(entry.name, pattern) for pattern in options.ignore):\",\"            continue\",\"        if options.no_symlinks and entry.is_link:\",\"            continue\",\"        if options.only_dirs and not (entry.is_dir or (options.show_symlinks and entry.points_to_dir)):\",\"            continue\",\"        if options.only_files and not recursing and not (entry.is_file or (options.show_symlinks and entry.is_link and not entry.points_to_dir)):\",\"            continue\",\"        filtered.append(entry)\",\"    return sorted_entries(filtered, options)\",\"\",\"\",\"def quote_name(name: str, no_quotes: bool) -> str:\",\"    if no_quotes or not any(char.isspace() for char in name):\",\"        return name\",\"    if \\\"'\\\" not in name:\",\"        return f\\\"'{name}'\\\"\",\"    return '\\\"' + name.replace('\\\"', '\\\\\\\\\\\"') + '\\\"'\",\"\",\"\",\"def classify(entry: Entry, options: Options) -> str:\",\"    if options.classify == \\\"never\\\" or (options.classify in {\\\"auto\\\", \\\"automatic\\\"} and not sys.stdout.isatty()):\",\"        return \\\"\\\"\",\"    if entry.is_dir:\",\"        return \\\"/\\\"\",\"    if entry.is_link:\",\"        return \\\"@\\\"\",\"    return \\\"\\\"\",\"\",\"\",\"def display_name(entry: Entry, options: Options, links: bool = False) -> str:\",\"    if options.absolute in {\\\"on\\\", \\\"follow\\\"}:\",\"        path = entry.path.absolute() if options.absolute == \\\"on\\\" else entry.path.resolve()\",\"        name = str(path)\",\"    elif entry.display_path is not None:\",\"        name = entry.display_path\",\"    else:\",\"        name = entry.name\",\"    name = quote_name(name, options.no_quotes)\",\"    name += classify(entry, options)\",\"    if links and entry.is_link:\",\"        try:\",\"            name += \\\" -> \\\" + os.readlink(entry.path)\",\"        except OSError:\",\"            pass\",\"    return name\",\"\",\"\",\"def windows_attributes(entry: Entry) -> str:\",\"    try:\",\"        bits = entry.st.st_file_attributes\",\"    except AttributeError:\",\"        bits = 0\",\"    first = \\\"d\\\" if entry.is_dir else \\\"l\\\" if entry.is_link else \\\"-\\\"\",\"    readonly = \\\"r\\\" if bits & getattr(stat, \\\"FILE_ATTRIBUTE_READONLY\\\", 1) else \\\"-\\\"\",\"    archive = \\\"a\\\" if bits & getattr(stat, \\\"FILE_ATTRIBUTE_ARCHIVE\\\", 32) else \\\"-\\\"\",\"    hidden = \\\"h\\\" if bits & getattr(stat, \\\"FILE_ATTRIBUTE_HIDDEN\\\", 2) else \\\"-\\\"\",\"    system = \\\"s\\\" if bits & getattr(stat, \\\"FILE_ATTRIBUTE_SYSTEM\\\", 4) else \\\"-\\\"\",\"    return first + readonly + archive + hidden + system\",\"\",\"\",\"def permissions(entry: Entry) -> str:\",\"    if os.name == \\\"nt\\\":\",\"        return windows_attributes(entry)\",\"    mode = entry.st.st_mode\",\"    kind = \\\"d\\\" if stat.S_ISDIR(mode) else \\\"l\\\" if stat.S_ISLNK(mode) else \\\"-\\\"\",\"    return kind + \\\"\\\".join(\",\"        char if mode & bit else \\\"-\\\"\",\"        for char, bit in zip(\\\"rwxrwxrwx\\\", (\",\"            stat.S_IRUSR, stat.S_IWUSR, stat.S_IXUSR, stat.S_IRGRP, stat.S_IWGRP,\",\"            stat.S_IXGRP, stat.S_IROTH, stat.S_IWOTH, stat.S_IXOTH,\",\"        ))\",\"    )\",\"\",\"\",\"def format_size(entry: Entry, options: Options) -> str:\",\"    if entry.is_dir:\",\"        return \\\"-\\\"\",\"    size = entry.size\",\"    if options.bytes_only:\",\"        return f\\\"{size:,}\\\"\",\"    base = 1024 if options.binary else 1000\",\"    symbols = [\\\"\\\", \\\"k\\\", \\\"M\\\", \\\"G\\\", \\\"T\\\", \\\"P\\\", \\\"E\\\"]\",\"    value = float(size)\",\"    unit = 0\",\"    while value >= base and unit < len(symbols) - 1:\",\"        value /= base\",\"        unit += 1\",\"    if unit == 0:\",\"        return str(size)\",\"    number = f\\\"{value:.1f}\\\" if value < 10 else str(round(value))\",\"    return number + symbols[unit]\",\"\",\"\",\"def format_time(timestamp: float, style: str) -> str:\",\"    value = datetime.fromtimestamp(timestamp).astimezone()\",\"    now = datetime.now().astimezone()\",\"    if style == \\\"long-iso\\\":\",\"        return value.strftime(\\\"%Y-%m-%d %H:%M\\\")\",\"    if style == \\\"full-iso\\\":\",\"        fraction = f\\\"{value.microsecond:06d}\\\" + \\\"000\\\"\",\"        return value.strftime(\\\"%Y-%m-%d %H:%M:%S.\\\") + fraction + value.strftime(\\\" %z\\\")\",\"    if style == \\\"iso\\\":\",\"        return value.strftime(\\\"%m-%d %H:%M\\\" if value.year == now.year else \\\"%Y-%m-%d\\\")\",\"    if style.startswith(\\\"+\\\"):\",\"        return value.strftime(style[1:].split(\\\"\\\\n\\\", 1)[0])\",\"    if value.year == now.year:\",\"        return f\\\"{value.day:2d} {value.strftime('%b')} {value.strftime('%H:%M')}\\\"\",\"    return f\\\"{value.day:2d} {value.strftime('%b')}  {value.year}\\\"\",\"\",\"\",\"def table_cells(entry: Entry, options: Options) -> list[str]:\",\"    cells: list[str] = []\",\"    if not options.no_permissions:\",\"        cells.append(permissions(entry))\",\"    if not options.no_filesize:\",\"        cells.append(format_size(entry, options))\",\"    for time_type in options.time_types:\",\"        timestamp = entry.st.st_mtime\",\"        if time_type == \\\"accessed\\\":\",\"            timestamp = entry.st.st_atime\",\"        elif time_type in {\\\"changed\\\", \\\"created\\\"}:\",\"            timestamp = entry.st.st_ctime\",\"        cells.append(format_time(timestamp, options.time_style))\",\"    return cells\",\"\",\"\",\"def render_long(entries: list[Entry], options: Options, tree_prefixes: list[str] | None = None) -> list[str]:\",\"    rows = [table_cells(entry, options) for entry in entries]\",\"    widths = [max((len(row[index]) for row in rows), default=0) for index in range(max((len(row) for row in rows), default=0))]\",\"    lines: list[str] = []\",\"    for row_index, (entry, row) in enumerate(zip(entries, rows)):\",\"        rendered = []\",\"        for index, cell in enumerate(row):\",\"            left = index in ({len(row) - len(options.time_types)} if options.time_types else set())\",\"            rendered.append(cell.ljust(widths[index]) if left else cell.rjust(widths[index]))\",\"        prefix = (\\\" \\\".join(rendered) + \\\" \\\") if rendered else \\\"\\\"\",\"        tree = tree_prefixes[row_index] if tree_prefixes else \\\"\\\"\",\"        lines.append(prefix + tree + display_name(entry, options, links=True))\",\"    return lines\",\"\",\"\",\"def render_names(entries: list[Entry], options: Options) -> list[str]:\",\"    if options.mode == \\\"long\\\":\",\"        return render_long(entries, options)\",\"    return [display_name(entry, options, links=options.mode == \\\"tree\\\") for entry in entries]\",\"\",\"\",\"def tree_rows(roots: list[Entry], options: Options) -> tuple[list[Entry], list[str]]:\",\"    entries: list[Entry] = []\",\"    prefixes: list[str] = []\",\"\",\"    def add(entry: Entry, depth: int, ancestors_last: list[bool], last: bool) -> None:\",\"        entries.append(entry)\",\"        prefix = \\\"\\\".join(\\\"    \\\" if was_last else \\\"│   \\\" for was_last in ancestors_last)\",\"        if depth:\",\"            prefix += \\\"└── \\\" if last else \\\"├── \\\"\",\"        prefixes.append(prefix)\",\"        if not entry.is_dir or entry.is_dot or (options.level is not None and options.level <= depth):\",\"            return\",\"        try:\",\"            nested = children(entry.path, options, True)\",\"        except OSError:\",\"            return\",\"        for index, child in enumerate(nested):\",\"            add(child, depth + 1, ancestors_last + ([last] if depth else []), index == len(nested) - 1)\",\"\",\"    for root_index, root in enumerate(roots):\",\"        add(root, 0, [], root_index == len(roots) - 1)\",\"    return entries, prefixes\",\"\",\"\",\"def render_tree(roots: list[Entry], options: Options) -> list[str]:\",\"    entries, prefixes = tree_rows(roots, options)\",\"    if options.mode == \\\"long\\\":\",\"        return render_long(entries, options, prefixes)\",\"    return [prefix + display_name(entry, options, links=True) for entry, prefix in zip(entries, prefixes)]\",\"\",\"\",\"def path_entry(raw: str, options: Options) -> Entry:\",\"    path = Path(raw)\",\"    st = path.lstat()\",\"    name = path.name or raw\",\"    return Entry(path, name, display_path=raw, _stat=st)\",\"\",\"\",\"def windows_io_message(error: OSError) -> str:\",\"    if getattr(error, \\\"winerror\\\", None) == 2 or error.errno == 2:\",\"        return \\\"系统找不到指定的文件。 (os error 2)\\\" if os.name == \\\"nt\\\" else \\\"No such file or directory (os error 2)\\\"\",\"    return str(error)\",\"\",\"\",\"def run(options: Options) -> int:\",\"    raw_paths = options.paths\",\"    if not raw_paths and options.stdin:\",\"        separator = os.environ.get(\\\"EZA_STDIN_SEPARATOR\\\", \\\"\\\\n\\\")\",\"        raw_paths = [item for item in sys.stdin.read().split(separator) if item]\",\"    if not raw_paths:\",\"        raw_paths = [\\\".\\\"]\",\"\",\"    files: list[Entry] = []\",\"    directories: list[Entry] = []\",\"    status = 0\",\"    for raw in raw_paths:\",\"        try:\",\"            entry = path_entry(raw, options)\",\"        except OSError as error:\",\"            sys.stderr.write(f\\\"{rust_debug(raw)}: {windows_io_message(error)}\\\\n\\\")\",\"            status = 2\",\"            continue\",\"        if entry.points_to_dir and not options.treat_dirs:\",\"            directories.append(entry)\",\"        else:\",\"            files.append(entry)\",\"\",\"    files = sorted_entries([entry for entry in files if not any(fnmatch.fnmatchcase(entry.name, p) for p in options.ignore)], options)\",\"    output: list[str] = []\",\"    if files:\",\"        output.extend(render_names(files, options))\",\"\",\"    if options.tree:\",\"        roots = directories + [entry for entry in files if entry.is_dir]\",\"        if roots:\",\"            if output and files:\",\"                output.append(\\\"\\\")\",\"            output.extend(render_tree(roots, options))\",\"    else:\",\"        only_directory = len(directories) == 1 and not files\",\"        queue: list[tuple[Entry, int]] = [(entry, 0) for entry in directories]\",\"        first_block = not files\",\"        position = 0\",\"        while position < len(queue):\",\"            directory, depth = queue[position]\",\"            position += 1\",\"            try:\",\"                listed = children(directory.path, options, options.recurse)\",\"            except OSError as error:\",\"                sys.stderr.write(f\\\"{directory.display_path or directory.path}: {error}\\\\n\\\")\",\"                continue\",\"            if not first_block:\",\"                output.